import java.io.*;import java.net.*;import java.net.http.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
public final class Equipment718ServerCheck {
 static void ok(boolean b,String s){if(!b)throw new AssertionError(s);System.out.println("PASS: "+s);}
 static DataInputStream call(String token,String op,ServerCheck.Writer writer)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream o=new DataOutputStream(b);o.writeInt(GunnyServer.MAGIC);o.writeUTF(op);if(writer!=null)writer.write(o);HttpRequest.Builder r=HttpRequest.newBuilder(URI.create(ServerCheck.base+"/api")).header("Content-Type","application/octet-stream").header("X-Gunny-Arsenal","2").header("X-Gunny-Equipment","1").header("X-Gunny-Client","2");if(token!=null)r.header("Authorization","Bearer "+token);DataInputStream in=new DataInputStream(new ByteArrayInputStream(ServerCheck.HTTP.send(r.POST(HttpRequest.BodyPublishers.ofByteArray(b.toByteArray())).build(),HttpResponse.BodyHandlers.ofByteArray()).body()));if(in.readUnsignedByte()!=0)throw new IOException(in.readUTF());return in;}
 static void reject(String t,String op,ServerCheck.Writer w,String message)throws Exception{boolean blocked=false;try{call(t,op,w);}catch(IOException e){blocked=true;}ok(blocked,message);}
 static String login(String mail)throws Exception{return call(null,"login",o->{o.writeUTF(mail);o.writeUTF("test-password-123");}).readUTF();}
 static void exchange(String t,int amount,String key)throws Exception{call(t,"exchange",o->{o.writeInt(amount);o.writeUTF(key);});}
 static void equip(String t,int k,int item)throws Exception{call(t,"equip",o->{o.writeByte(k);o.writeByte(item);});}
 static void rules(){Battle b=new Battle(new Arsenal717ServerCheck.Ground());b.start(true);Battle.Unit u=b.units[0];u.weapon=5;ItemRules.apply(u,125);ok(u.attackBonus==25&&u.hp==2055&&u.energy==300,"Five separate clothes each add 5 attack, HP and stamina");ok(b.make(45,50).damage==355,"Attack from worn clothing changes projectile damage");u.energy=300;ItemRules.weapon(u,4);ok(u.maxHp==2090&&u.maxEnergy==270&&u.energy==270,"Switching to fridge recomputes weapon defense and luck");ItemRules.weapon(u,5);ok(u.maxEnergy==300&&u.energy==270,"Switching back does not refill stamina");b.active=1;b.next();ok(u.energy==300,"Own next turn restores equipment stamina cap");u.hp=u.maxHp-10;b.prop(3);ok(u.hp==u.maxHp,"Healing respects equipment maximum HP");ItemRules.apply(u,3);ok(u.attackBonus==5,"A complete outfit contributes five, not five separate parts");ok(!ItemRules.validMask(127),"Full outfit and loose clothing cannot stack simultaneously");Set<String> sets=new HashSet<>();for(int w:new int[]{0,3,5,9,2,4,7,1})sets.add(ItemRules.attack(0,w)+":"+ItemRules.defense(0,w)+":"+ItemRules.luck(0,w));ok(sets.size()==8,"Every weapon has a distinct stat combination");}
 static final class SlowStore extends CloudStore {final CloudStore.Memory memory=new CloudStore.Memory();final CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);SlowStore(){super(true);}void register(String e,String p,String n)throws Exception{memory.register(e,p,n);}CloudStore.Login login(String e,String p)throws Exception{return memory.login(e,p);}CloudStore.Profile profile(String id){return memory.profile(id);}CloudStore.Profile equip(String id,int k,int i)throws Exception{entered.countDown();release.await(3,TimeUnit.SECONDS);return memory.equip(id,k,i);}}
 static void slowRoom()throws Exception{SlowStore slow=new SlowStore();slow.register("slow@718.test","test-password-123","Slow");try(GunnyServer server=new GunnyServer(new InetSocketAddress("127.0.0.1",0),Path.of("backend/assets"),slow)){ServerCheck.base="http://127.0.0.1:"+server.port();String token=login("slow@718.test");int id=call(token,"create",o->{o.writeByte(1);o.writeByte(0);o.writeByte(-1);}).readInt();GunnyServer.Room room=server.rooms.get(id);CompletableFuture<Void> work=CompletableFuture.runAsync(()->{try{equip(token,1,0);}catch(Exception e){throw new RuntimeException(e);}});ok(slow.entered.await(5,TimeUnit.SECONDS),"Slow database equipment call begins");long start=System.currentTimeMillis();synchronized(room){ok(!room.canStart(),"Room cannot start while equipment is committing");}ok(System.currentTimeMillis()-start<1000,"Database wait does not hold the room or block simulation ticks");slow.release.countDown();work.get(5,TimeUnit.SECONDS);ok(room.equipmentPending==0,"Equipment commit releases the start guard");}}
 public static void main(String[] args)throws Exception{rules();CloudStore.Memory store=new CloudStore.Memory();store.register("a@718.test","test-password-123","A");store.register("b@718.test","test-password-123","B");try(GunnyServer server=new GunnyServer(new InetSocketAddress("127.0.0.1",0),Path.of("backend/assets"),store)){ServerCheck.base="http://127.0.0.1:"+server.port();String a=login("a@718.test"),b=login("b@718.test");GunnyServer.Session sa=server.sessions.get(a),sb=server.sessions.get(b);CloudStore.Profile p=sa.profile;p.coins=100000;exchange(a,1000,"first");ok(p.coins==0&&p.shoppingMoney==1000,"Server exchanges exactly 100 earned coins for each note");exchange(a,1000,"first");ok(p.coins==0&&p.shoppingMoney==1000,"Repeated exchange key is idempotent");reject(a,"exchange",o->{o.writeInt(1);o.writeUTF("first");},"Exchange key cannot be reused with another amount");reject(a,"exchange",o->{o.writeInt(-1);o.writeUTF("negative");},"Negative exchange amount is rejected");reject(a,"exchange",o->{o.writeInt(1);o.writeUTF("insufficient");},"Insufficient earned coins cannot create notes");p.coins=100;ExecutorService pool=Executors.newFixedThreadPool(2);try{List<Future<?>> futures=new ArrayList<>();for(int k=0;k<2;k++)futures.add(pool.submit(()->{try{exchange(a,1,"concurrent");}catch(Exception e){throw new RuntimeException(e);}}));for(Future<?> f:futures)f.get();}finally{pool.shutdown();}ok(p.coins==0&&p.shoppingMoney==1001,"Concurrent duplicate exchange debits once");call(a,"checkout",o->{o.writeByte(0);for(int k=0;k<7;k++)o.writeShort(k==3?4:0);});ok(p.shoppingMoney==871&&p.coins==0&&(p.wardrobe[2]&4)!=0,"Shop charges notes and leaves earned coins untouched");p.coins=100000;int saved=p.shoppingMoney;p.shoppingMoney=0;reject(a,"checkout",o->{o.writeByte(0);for(int k=0;k<7;k++)o.writeShort(k==2?4:0);},"Earned coins cannot directly pay shopping prices");p.coins=0;p.shoppingMoney=saved;equip(a,3,2);ok(p.wornMask==9&&p.custom,"Equipping a hat replaces complete-outfit mode");equip(a,3,-1);ok(p.wornMask==1&&(p.wardrobe[2]&4)!=0,"Removing returns the item without losing ownership");reject(a,"equip",o->{o.writeByte(3);o.writeByte(9);},"Cannot equip unowned clothing");equip(a,3,2);int room=call(a,"create",o->{o.writeByte(1);o.writeByte(0);o.writeByte(-1);}).readInt();call(b,"join",o->{o.writeInt(room);o.writeByte(1);});GunnyServer.Room r=server.rooms.get(room);r.strict=true;sb.armed=true;equip(a,3,-1);ok(!sb.armed&&r.avatars[0].wornMask==1,"Waiting-room equipment resets ready state and broadcasts the new mask");equip(a,3,2);equip(a,0,-1);ok(!r.canStart(),"Room cannot start with an empty weapon slot");equip(a,0,0);call(b,"ready",o->o.writeBoolean(true));call(a,"start",null);ok(r.battle.units[0].maxHp==2045&&r.battle.units[0].maxEnergy==265&&r.battle.units[0].attackBonus==5,"Live server starts battle with authoritative equipment stats");int mask=p.wornMask;reject(a,"equip",o->{o.writeByte(3);o.writeByte(-1);},"Equipment is locked during battle");ok(p.wornMask==mask,"Rejected battle edit leaves equipped stats intact");}
 slowRoom();System.out.println("All equipment 7.1.8 server checks passed");}
}
